import{H as e,at as t,it as n,vt as r}from"./chunks/framework.dmHZ7NHG.js";var i=JSON.parse(`{"title":"Thermodynamics — Energy & Entropy","description":"","frontmatter":{},"headers":[],"relativePath":"docs/science/thermodynamics.md","filePath":"docs/science/thermodynamics.md"}`),a={name:`docs/science/thermodynamics.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="thermodynamics-—-energy-entropy" tabindex="-1">Thermodynamics — Energy &amp; Entropy <a class="header-anchor" href="#thermodynamics-—-energy-entropy" aria-label="Permalink to “Thermodynamics — Energy &amp; Entropy”">​</a></h1><h2 id="the-sealed-truth" tabindex="-1">The Sealed Truth <a class="header-anchor" href="#the-sealed-truth" aria-label="Permalink to “The Sealed Truth”">​</a></h2><p><strong>Theorem:</strong> <code>Thermodynamics.lean</code> (7 theorems, all <code>by decide</code>)</p><p>The first law conserves energy: ΔU = Q − W (heat in minus work out). The second law forbids entropy decrease — heat flows hot→cold, never cold→hot without work. Carnot efficiency never reaches 100%. Kelvin scale floors at absolute zero (0K = −273.15°C). Charles&#39;s law keeps V/T constant. Specific heat is linear in ΔT.</p><p><strong>Why sealed:</strong> These are pure arithmetic. Energy in = energy out. Entropy monotones. No paradox, no quantum surprise — classical thermodynamics as decidable facts.</p><hr><h2 id="the-honest-boundary" tabindex="-1">The Honest Boundary <a class="header-anchor" href="#the-honest-boundary" aria-label="Permalink to “The Honest Boundary”">​</a></h2><p><strong>What thermodynamics CANNOT prove:</strong></p><ul><li>Whether entropy applies to information (Shannon entropy vs physical)</li><li>Whether &quot;heat death&quot; is inevitable (depends on universal initial conditions)</li><li>Why entropy increases (time&#39;s arrow — that&#39;s cosmology, not thermodynamics)</li><li>What heat &quot;is&quot; at the atomic scale (that&#39;s statistical mechanics, sealed separately)</li></ul><p><strong>Honest scope:</strong> Thermodynamics seals the MACROSCOPIC LAWS. Statistical mechanics seals the ATOMIC BASIS. Neither proves they are the same thing.</p><hr><h2 id="the-metaphysical-pair" tabindex="-1">The Metaphysical Pair <a class="header-anchor" href="#the-metaphysical-pair" aria-label="Permalink to “The Metaphysical Pair”">​</a></h2><p><strong>The Question:</strong> <em>Does the second law imply the universe tends toward chaos?</em></p><p><strong>The Trinity:</strong></p><table tabindex="0"><thead><tr><th>Perspective</th><th>What It Proves</th><th>What It Cannot</th></tr></thead><tbody><tr><td><strong>Decidable (Sealed)</strong></td><td>Entropy in a closed system never decreases; this is a mathematical tautology on the probability distribution of microstates. Highest-probability states are most disordered.</td><td>Whether the universe IS closed; whether disorder=meaninglessness; whether emergence violates the law</td></tr><tr><td><strong>Honest Boundary</strong></td><td>In a closed system, statistical order is improbable and requires external work to maintain.</td><td>Whether life/thought/beauty is &quot;against&quot; entropy or &quot;within&quot; it; whether order matters</td></tr><tr><td><strong>Metaphysical</strong></td><td>If entropy always increases, does meaning/beauty/life/consciousness require constant work against the tide? Does mortality follow?</td><td>Whether increased entropy is <em>bad</em>, whether the universe &quot;should&quot; last forever, whether heat death is cosmologically inevitable</td></tr></tbody></table><p><strong>The court decides:</strong> Whether entropy implies nihilism is not a theorem — it&#39;s a choice about meaning. Thermodynamics seals the mechanics. Philosophy seals the meaning.</p><hr><h2 id="read-the-sealed-proof" tabindex="-1">Read the Sealed Proof <a class="header-anchor" href="#read-the-sealed-proof" aria-label="Permalink to “Read the Sealed Proof”">​</a></h2><p><a href="./../../lean/Thermodynamics.lean">Link to Thermodynamics.lean</a></p><ul><li><code>first_law_conserves_energy</code></li><li><code>second_law_entropy_monotone</code></li><li><code>carnot_efficiency_bound</code></li><li><code>kelvin_scale_floor</code></li><li><code>charles_law_volume_temperature</code></li><li><code>specific_heat_linear</code></li></ul><p>Each proven <code>by decide</code> — recompute it yourself.</p><hr><h2 id="the-research-question" tabindex="-1">The Research Question <a class="header-anchor" href="#the-research-question" aria-label="Permalink to “The Research Question”">​</a></h2><p>If entropy is the only asymmetry in time, and consciousness is a localized decrease in entropy (maintained by eating, breathing, working), then:</p><ol><li>Is consciousness fundamentally a fight against entropy?</li><li>Do meaning-making systems (art, music, science) defy entropy locally?</li><li>Does this frame explain why beauty requires effort?</li></ol><p><strong>These are open.</strong> Thermodynamics does not answer them. Only the court can.</p>`,26)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};